def test_read_hk():
    hkpff = pypff.io.hkpff('hk-data/hk.pff')
    hk_info = hkpff.readhk()
    for k in hk_info.keys():
        for kk in hk_info[k].keys():
            try:
                v = float(expected_hk_results[k][kk])
            except:
                v = expected_hk_results[k][kk]
            assert hk_info[k][kk][0] == v
